void galois_multiply(const uint8_t *x, const uint8_t *y, uint8_t *result) {
    uint8_t z[16] = {0};
    uint8_t v[16];
    memcpy(v, y, 16);
    for (int i = 0; i < 128; ++i) {
        if (x[i / 8] & (1 << (7 - (i % 8)))) {
            xor_blocks(z, z, v, 16);
        }
        int carry = v[15] & 1;
        for (int j = 15; j > 0; --j) {
            v[j] = (v[j] >> 1) | ((v[j - 1] & 1) << 7);
        }
        v[0] >>= 1;
        if (carry) {
            v[0] ^= 0xe1;
        }
    }
    memcpy(result, z, 16);
}
